    expect(MOCK_LLM_CLI_USAGE).toContain('--sequence')
  })

  it('parses every request and listener option', () => {
    expect(parseMockLlmCliArgs([
      '--sequence', 'connection_refused,partial_disconnect,success',
      '--host', 'localhost',
      '--port', '9010',
      '--api-key', 'mock-key',
      '--listen-delay-ms', '100',
      '--repeat-last',
